export type RecurrenceCadence = "daily" | "weekly";

/**
 * A rule a background job turns into ordinary issues. Dates (`startsOn`,
 * `lastOccurrenceOn`) are `YYYY-MM-DD` strings; `weekday` is the ISO weekday,
 * 1 = Monday … 7 = Sunday.
 */
