    .orderBy(sql`"recurring_issues".rowid`)
    .all()
    .map(toRecurringIssue);
}

export async function setPaused(
  orgId: OrgId,
  id: string,
  paused: boolean,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .returning()
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function setLastOccurrenceOn(
  orgId: OrgId,
  id: string,
  occurrenceOn: string,
): Promise<void> {
  getDb()
    .update(recurringIssues)
    .set({ lastOccurrenceOn: occurrenceOn, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .run();
}
