cat > src/server/jobs/recurring-issue-job.ts <<'EOF'
/**
 * Files one ordinary issue per due recurring-issue rule, on behalf of the rule's creator.
 *
 * Must call (do not reimplement): createIssue, can, isArchived
 */
import { can, PermissionDeniedError } from "@/lib/permissions";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { projectResource } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

const DAY_MS = 86_400_000;

function parseDay(day: string): number {
  const [year, month, date] = day.split("-").map(Number) as [number, number, number];
  const at = new Date(Date.UTC(2000, month - 1, date));
  at.setUTCFullYear(year);
  return at.getTime();
}

function formatDay(ms: number): string {
  const at = new Date(ms);
  const year = String(at.getUTCFullYear()).padStart(4, "0");
  const month = String(at.getUTCMonth() + 1).padStart(2, "0");
  const date = String(at.getUTCDate()).padStart(2, "0");
  return `${year}-${month}-${date}`;
}

/** The calendar day `now` falls on in `timeZone`, as `YYYY-MM-DD`. */
function localDay(now: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const pick = (type: string): string =>
    parts.find((part) => part.type === type)?.value ?? "";
  return `${pick("year").padStart(4, "0")}-${pick("month")}-${pick("day")}`;
}

/** ISO weekday of a `YYYY-MM-DD` day: 1 = Monday … 7 = Sunday. */
function isoWeekday(day: string): number {
  const dow = new Date(parseDay(day)).getUTCDay();
  return dow === 0 ? 7 : dow;
}

/**
 * The latest occurrence of `rule` that has started by `now`, or null. A day
 * has started once local time in the rule's zone reaches its 00:00, which is
 * exactly when the zone's calendar date becomes that day.
 */
export function latestOccurrence(rule: RecurringIssue, now: Date): string | null {
  const today = localDay(now, rule.timezone);
  let latest = today;

  if (rule.cadence === "weekly") {
    if (rule.weekday === null) return null;
    const back = (isoWeekday(today) - rule.weekday + 7) % 7;
    latest = formatDay(parseDay(today) - back * DAY_MS);
  }

  return latest >= rule.startsOn ? latest : null;
}

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listActiveRules();

    for (const rule of rules) {
      try {
        const outcome = await processRule(rule, now);
        if (outcome === "created") result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          ruleId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function processRule(
  rule: RecurringIssue,
  now: Date,
): Promise<"created" | "skipped"> {
  const occurrence = latestOccurrence(rule, now);
  if (occurrence === null) return "skipped";
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return "skipped";
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null || isArchived(project)) return "skipped";

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  if (creator === null || creator.status !== "active") {
    await pause(rule);
    return "skipped";
  }

  const actor: Actor = {
    userId: rule.createdBy,
    orgId: rule.orgId,
    role: creator.role,
  };
  if (!can(actor, "issue:create", projectResource(project))) {
    await pause(rule);
    return "skipped";
  }

  const assigneeId = await activeAssignee(rule);

  try {
    await createIssue(actor, {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${occurrence})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      await pause(rule);
      return "skipped";
    }
    throw error;
  }

  await recurringRepo.setLastOccurrenceOn(rule.orgId, rule.id, occurrence);
  return "created";
}

async function activeAssignee(rule: RecurringIssue): Promise<UserId | null> {
  if (rule.assigneeId === null) return null;
  const assignee = await memberRepo.findMember(rule.orgId, rule.assigneeId);
  return assignee !== null && assignee.status === "active" ? rule.assigneeId : null;
}

async function pause(rule: RecurringIssue): Promise<void> {
  await recurringRepo.setPaused(rule.orgId, rule.id, true);
}
EOF
